<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Announcement extends Model { protected $fillable=['parish_id','created_by','title','body','importance']; public function parish(){return $this->belongsTo(Parish::class);} public function creator(){return $this->belongsTo(User::class,'created_by');} public function recipients(){return $this->belongsToMany(User::class,'announcement_recipients')->withPivot('read_at')->withTimestamps();} }
